examples.query:
query Products @inContext(country: GB) {
  woolSweater: product(handle: "wool-sweater") {
    title
  }
  alarmClock: product(handle: "alarm-clock") {
    title
  }
  products(first: 2) {
    nodes {
      title
    }
  }
}

query ProductTitle @inContext(country: CA, language: FR) {
  product(handle: "wool-sweater") {
    title
    description
  }
}

query ProductPricing @inContext(country: CA) {
  product(handle: "wool-sweater") {
    variants(first: 1) {
      nodes {
        price {
          amount
          currencyCode
        }
      }
    }
  }
}

query getProductMedia($id: ID!) {
  product(id: $id) {
    id
    media(first: 10) {
      edges {
        node {
          mediaContentType
          alt
          ...mediaFieldsByType
        }
      }
    }
  }
}

fragment mediaFieldsByType on Media {
  ... on ExternalVideo {
    id
    embeddedUrl
  }
  ... on MediaImage {
    image {
      url
    }
  }
  ... on Model3d {
    sources {
      url
      mimeType
      format
      filesize
    }
  }
  ... on Video {
    sources {
      url
      mimeType
      format
      height
      width
    }
  }
}
